-- 1. Insert Topic
ON CONFLICT (id) DO UPDATE SET 
  name = EXCLUDED.name, 
  description = EXCLUDED.description,
  display_order = EXCLUDED.display_order;

-- 2. Insert Vocabulary (794 phrases)
ON CONFLICT (topic_id, word_en) DO NOTHING;

-- 3. Insert Translations
-- Using a CTE to map vocabulary IDs
WITH vocab_ids AS (
  SELECT id, word_en FROM vocabulary WHERE topic_id = 42
)
ON CONFLICT (vocabulary_id, language) DO UPDATE SET translation = EXCLUDED.translation;

